import { sql } from 'drizzle-orm';
import {
  check,
  foreignKey,
  index,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from 'drizzle-orm/pg-core';
import { gyms } from './gyms';
import { planDays } from './plan-days';
import { plans } from './plans';
import { users } from './users';

/**
 * Gym-owned (RLS on `gym_id`). One workout a member did (or is doing: `finished_at` NULL). The id
 * is generated by the client so an offline write can be retried safely. Sessions are history and
 * never deleted by `gym_app`. The plan references are `ON DELETE SET NULL (plan_id)` /
 * `(plan_day_id)` in the migration (column-list syntax, which drizzle cannot express): a plain
 * SET NULL would also null `gym_id`.
 */
export const workoutSessions = pgTable(
  'workout_sessions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    gymId: uuid('gym_id')
      .notNull()
      .references(() => gyms.id),
    memberId: uuid('member_id')
      .notNull()
      .references(() => users.id),
    planId: uuid('plan_id'),
    planDayId: uuid('plan_day_id'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull(),
    finishedAt: timestamp('finished_at', { withTimezone: true }),
    notes: text('notes'),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [
    foreignKey({
      name: 'workout_sessions_plan_gym_fk',
      columns: [t.planId, t.gymId],
      foreignColumns: [plans.id, plans.gymId],
    }).onDelete('set null'),
    foreignKey({
      name: 'workout_sessions_plan_day_gym_fk',
      columns: [t.planDayId, t.gymId],
      foreignColumns: [planDays.id, planDays.gymId],
    }).onDelete('set null'),
    // Target of workout_sets' composite foreign key.
    unique('workout_sessions_id_gym_uq').on(t.id, t.gymId),
    check(
      'workout_sessions_finished_chk',
      sql`${t.finishedAt} is null or ${t.finishedAt} >= ${t.startedAt}`,
    ),
    check('workout_sessions_notes_chk', sql`${t.notes} is null or char_length(${t.notes}) <= 1000`),
    index('workout_sessions_gym_member_started_idx').on(t.gymId, t.memberId, t.startedAt.desc()),
    // The "is there an open session?" lookup.
    index('workout_sessions_open_idx')
      .on(t.gymId, t.memberId)
      .where(sql`${t.finishedAt} is null`),
    // Keeps the plan-day SET NULL (plan edits delete days) from scanning every session.
    index('workout_sessions_plan_day_idx')
      .on(t.planDayId)
      .where(sql`${t.planDayId} is not null`),
  ],
);
